package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.dto.Requests.CreateUserRequest;import com.example.riskplatform.entity.*;import com.example.riskplatform.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class SystemService{private final SysUserMapper um;private final SysRoleMapper rm;private final SysDepartmentMapper dm;private final UserAuthMapper auth;private final PasswordEncoder encoder;public List<SysUser>users(){List<SysUser>x=um.selectList(new LambdaQueryWrapper<SysUser>().orderByDesc(SysUser::getId));x.forEach(u->u.setPasswordHash(null));return x;}public List<SysRole>roles(){return rm.selectList(new LambdaQueryWrapper<SysRole>().orderByAsc(SysRole::getId));}public List<SysDepartment>departments(){return dm.selectList(new LambdaQueryWrapper<SysDepartment>().orderByAsc(SysDepartment::getSortNo));}@Transactional public SysUser createUser(CreateUserRequest r){if(auth.findByUsername(r.getUsername())!=null)throw new BusinessException("用户名已存在");SysUser u=new SysUser();u.setUsername(r.getUsername());u.setPasswordHash(encoder.encode(r.getPassword()));u.setRealName(r.getRealName());u.setDeptId(r.getDeptId());u.setSecurityLevel(r.getSecurityLevel());u.setStatus(1);um.insert(u);for(Long rid:r.getRoleIds())auth.insertUserRole(u.getId(),rid);u.setPasswordHash(null);return u;}@Transactional public void assignRoles(Long uid,List<Long>ids){auth.deleteUserRoles(uid);for(Long id:ids)auth.insertUserRole(uid,id);}}
